	private void btn_minimize_Click(object sender, EventArgs e)
	{
		base.WindowState = FormWindowState.Minimized;
	}

	private void btn_maximize_Click(object sender, EventArgs e)
	{
		if (base.WindowState != FormWindowState.Maximized)
		{
			base.WindowState = FormWindowState.Maximized;
		}
		else
		{
			base.WindowState = FormWindowState.Normal;
		}
	}

	public void btn_close_Click(object sender, EventArgs e)
	{
		try
		{
			if (clsVar.varRuntime.MachineID == 7)
			{
				if (clsAppMarbleVars.cMachine.runSystem.Run)
				{
					F_Intro.appMachine2.ShowWarning(buLangTranslate.preMotionWarning.SystemisRunning, Color.Gold);
				}
				else if (clsAppMarbleVars.cMachine.runSystem.Pause)
				{
					F_Intro.appMachine2.ShowWarning(buLangTranslate.preMotionWarning.SsytemisPaused, Color.Gold);
				}
				else
				{
					clsLocalCommand.Exit();
				}
			}
		}
		catch (Exception)
		{
		}
	}

	private void spn_Enter(object sender, EventArgs e)
	{
		buSpin buSpin2 = sender as buSpin;
		buSpin2.Display.BackColor = buEyeVars.parVisual.colorDataFocus;
		buSpin2.SelectAll();
	}

	public void spn_Leave(object sender, EventArgs e)
	{
		buSpin buSpin2 = sender as buSpin;
	}

	private void spn_ValueClicked(object sender, EventArgs e)
	{
		buSpin buSpin2 = sender as buSpin;
		if (AppBool.TouchPad)
		{
			F_KeyPadNumV1 f_KeyPadNumV = new F_KeyPadNumV1();
			f_KeyPadNumV.StartPosition = FormStartPosition.CenterParent;
			f_KeyPadNumV.Caption = buSpin2.Caption.Caption;
			f_KeyPadNumV.ShowDialog(buSpin2.Value.ToString());
			if (buNumeric5.IsNumeric(f_KeyPadNumV.Value))
			{
				buSpin2.Value = double.Parse(f_KeyPadNumV.Value);
			}
		}
	}

	private void btn_Click(object sender, EventArgs e)
	{
		Control control = sender as Control;
		if (control.Name == btn_menuright.Name)
		{
			btn_menuleft.Left = 1;
			pnl_coords.Left = 1580;
			pnl_coords.Width = 341;
			pnl_maincmd.Width = 1582;
			pnl_commnadtop.Width = 1576;
			lbl_coordstatus.Visible = true;
			clsAppMarbleItems.frmCoordsV2.pnl_base.Visible = true;
			btn_menuright.Visible = false;
			MarbleTempVars.DockRightEnable = true;
			if (!MarbleTempVars.DockRightEnable)
			{
				pnl_down.Width = 1910;
			}
			else
			{
				pnl_down.Width = 1575;
			}
			clsAppMarbleItems.frmBottomPanelV1.pnl_base.Width = pnl_down.Width - 2;
			btn_menudown.Left = 840;
			btn_menuup.Left = 840;
		}
		if (control.Name == btn_menuleft.Name)
		{
			btn_menuleft.Left = 1;
			pnl_coords.Left = 1920;
			pnl_coords.Width = 1;
			pnl_maincmd.Width = 1920;
			pnl_commnadtop.Width = 1920;
			lbl_coordstatus.Visible = false;
			clsAppMarbleItems.frmCoordsV2.pnl_base.Visible = false;
			btn_menuright.Visible = true;
			MarbleTempVars.DockRightEnable = false;
			if (!MarbleTempVars.DockRightEnable)
			{
				pnl_down.Width = 1910;
			}
			else
			{
				pnl_down.Width = 1575;
			}
			clsAppMarbleItems.frmBottomPanelV1.pnl_base.Width = pnl_down.Width - 2;
			btn_menudown.Left = 840;
			btn_menuup.Left = 840;
		}
		if (control.Name == btn_menuup.Name)
		{
			pnl_down.Visible = true;
			pnl_maincmd.Height = 800;
			pnl_down.Left = 0;
			pnl_down.Height = 230;
			if (!MarbleTempVars.DockRightEnable)
			{
				pnl_down.Width = 1910;
			}
			else
			{
				pnl_down.Width = 1575;
			}
			clsAppMarbleItems.frmBottomPanelV1.pnl_base.Width = pnl_down.Width - 2;
			pnl_down.Top = pnl_maincmd.Height + pnl_maincmd.Top;
			btn_menuup.Visible = false;
			MarbleTempVars.DockBottomEnable = true;
		}
		if (control.Name == btn_menudown.Name)
		{
			pnl_down.Visible = false;
			pnl_down.Height = 1;
			pnl_down.Left = 0;
			pnl_maincmd.Height = 985;
			pnl_down.Top = pnl_maincmd.Height + pnl_maincmd.Top - 5;
			btn_menuup.Visible = true;
			clsAppMarbleItems.frmBottomPanelV1.MenuButtonColors(clsAppMarbleItems.frmBottomPanelV1.buTab_Main.SelectedIndex);
			MarbleTempVars.DockBottomEnable = false;
		}
	}

	private void lbl_warning_Click(object sender, EventArgs e)
	{
		lbl_warning.Visible = false;
	}

	private void F_Machine2_Load(object sender, EventArgs e)
	{
		btn_Click(btn_menudown, null);
		MarbleTempVars.DockRightEnable = true;
	}

	protected override void Dispose(bool disposing)
	{
		if (disposing && components != null)
		{
			components.Dispose();
		}
		base.Dispose(disposing);
	}

